// === Tab: mySketch ===

let avoiders=[]
let colors= ["#721121","#a5402d","#f15156","#ffc07f","#ffcf99"]
let overAllTexture

function setup() {
  createCanvas(600, 600);
  b=createGraphics(700, 700)
  angleMode(DEGREES)
  blendMode(MULTIPLY)
  for(let i=0; i<35; i++){
    avoiders.push(new avoider())
  }

  background(255);
  overAllTexture=createGraphics(width,height)
	overAllTexture.loadPixels()
	for(var i=0;i<width+50;i++){
		for(var o=0;o<height+50;o++){
			overAllTexture.set(i,o,color(150,noise(i/10,o/10)*random([0,0,0,50,100])))
}
    }
  overAllTexture.updatePixels()
    }

function draw() {
  clear()
  background(255, 240, 235);
	push()
		blendMode(MULTIPLY)
		image(overAllTexture,0,0)
	pop()
  for(let avoider of avoiders){
    avoider.update()
    avoider.relate()
    avoider.display()
  }
  b. background(255)
  b.erase();
  b.rect(50, 50, 600, 600);
  b.noErase();
  blendMode(SCREEN)
  drawingContext.shadowBlur = 75;
  drawingContext.shadowColor = 'white';
  image(b, -45, -45, 690, 690)
  drawingContext.shadowBlur= 0
  blendMode(MULTIPLY)
}

class avoider{
  constructor(){
    this.pos= createVector(random(0, width), random(0, height))
    this.vel= createVector(0, 0)
    this.acc= p5.Vector.random2D();
    this.color=color (random(colors))
    // this.acc.setMag(1)
  }

  update(){
    this.acc.setMag(0.01)
    this.vel.add(this.acc)
    this.pos.add(this.vel)
    this.vel.limit(2)

    //edges
    if(this.pos.x<-10){
      this.pos.x=width+10
    }
    if(this.pos.x>width+10){
      this.pos.x=-10
    }
    if(this.pos.y<-10){
      this.pos.y=height+10
    }
    if(this.pos.y>height+10){
      this.pos.y=-10
    }

  }

  relate(){
    for(let j=0; j<avoiders.length; j++){
      let distance = p5.Vector.dist(this.pos, avoiders[j].pos)
      if(distance < 50){
         this.pos.rotate(0.2)
        stroke(this.color)
        line(this.pos.x, this.pos.y, avoiders[j].pos.x, avoiders[j].pos.y)
         }
    }

  }

  display(){
    noStroke()
    // this.color.setAlpha(255)
    // stroke(this.color)
    this.color.setAlpha(255)
    fill(this.color)
    ellipse(this.pos.x, this.pos.y, 25)

  }
}

